function initTableResizer(n){const t=document.querySelectorAll(".table-resizable");t.forEach(function(t){const u=t.querySelectorAll("th"),i=n?`table_width_${n}`:null;let r={};if(i)try{const n=localStorage.getItem(i);n&&(r=JSON.parse(n))}catch(f){console.error("Lỗi đọc localStorage cho table width:",f)}u.forEach(function(n,t){const e=n.getAttribute("data-col-key")||`col_${t}`;if(i&&r[e]&&(n.style.width=`${r[e]}px`,n.style.minWidth=`${r[e]}px`),!n.querySelector(".resizer")){const f=document.createElement("div");f.classList.add("resizer");n.appendChild(f);let o=0,s=0;const l=function(t){o=t.clientX;s=n.offsetWidth;f.classList.add("resizing");document.addEventListener("mousemove",h);document.addEventListener("mouseup",c);t.preventDefault()},h=function(t){const r=t.clientX-o,i=Math.max(35,s+r);n.style.width=`${i}px`;n.style.minWidth=`${i}px`},c=function(){if(f.classList.remove("resizing"),document.removeEventListener("mousemove",h),document.removeEventListener("mouseup",c),i){const n={};u.forEach((t,i)=>{const r=t.getAttribute("data-col-key")||`col_${i}`;n[r]=t.offsetWidth});try{localStorage.setItem(i,JSON.stringify(n))}catch(n){console.error("Lỗi ghi localStorage cho table width:",n)}}};f.addEventListener("mousedown",l)}})})}function resetTableResizer(n){if(!n){console.warn("Cần truyền vào tableName để xóa cấu hình kích thước cột!");return}const t=`table_width_${n}`;try{localStorage.removeItem(t);const i=document.querySelectorAll(".table-resizable");i.forEach(function(n){const t=n.querySelectorAll("th");t.forEach(function(n){n.style.width="";n.style.minWidth=""})});console.log(`Đã reset kích thước cột cho bảng: ${n}`)}catch(i){console.error("Lỗi khi xóa cấu hình table width trong localStorage:",i)}}document.addEventListener("DOMContentLoaded",function(){["SortBy","IsDescending"].forEach(function(n){const t=document.getElementById(n);t&&!t.tomselect&&new TomSelect(t,{create:!1,maxOptions:100,closeAfterSelect:!0})})});document.addEventListener("DOMContentLoaded",function(){initTableResizer()});